('creature', 'demonrunner', 'Hind leg claw or running head butt', '4D6', 1, NULL, 'M.D.; the running head butt uses two melee attacks.', 1),
('creature', 'demonrunner', 'Running pounce', '5D6', 1, NULL, 'M.D.; uses two melee attacks. A victim under 15 feet (4.6 m) tall is 90% likely to be knocked down, losing initiative and two melee actions.', 2),
('creature', 'demonrunner', 'Power pounce', '1D6x10', 1, NULL, 'M.D.', 3),
('creature', 'demonrunner', 'Tail strike', '1D6', 1, NULL, 'M.D.', 4),
('creature', 'kryygorth-shellback', 'Horns', 'Supernatural P.S. damage +1D6', 1, NULL, 'M.D.; supernatural P.S. damage plus 1D6 M.D. from the horns.', 0),
('creature', 'kryygorth-shellback', 'Bite', '1', 1, NULL, 'One M.D.', 1),
('creature', 'kryygorth-shellback', 'Trample', '6D6', 1, NULL, 'M.D.; only when forced to run, and uses all three melee actions.', 2);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 creatures are in' AS assertion, count(*) AS got, 2 AS want
  FROM creatures WHERE slug IN ('demonrunner', 'kryygorth-shellback');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('demonrunner', 'kryygorth-shellback');
SELECT 'the creatures carry 8 attacks' AS assertion, count(*) AS got, 8 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('demonrunner', 'kryygorth-shellback');

